define({"topics":[{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_2.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e2714","topics":[]},{"title":"Applying LOTO - Cryocooler Compressor","shortdesc":"<p class=\"shortdesc\">Apply LOTO to the cryocooler compressor breaker on the MDP when servicing this item. Applying LOTO ensures a safe environment when servicing the F50 cryocooler compressor.<\/p>","href":"t_Applying-LOTO-CryocoolerCompressor-Premier_2.html","attributes":{"data-id":"id_2001782"},"menu":{"hasChildren":false},"tocID":"id_2001782-d46e2922","topics":[]},{"title":"Connecting the cryocooler hoses and cables - Equipment room","shortdesc":"<p class=\"shortdesc\">Follow this procedure to connect the cryocooler hoses and cables in the equipment room.<\/p>","href":"t_ConnectingTheEquipmentRoomHosesAndCables.html","attributes":{"data-id":"id_2001951"},"menu":{"hasChildren":false},"tocID":"id_2001951-d46e3026","topics":[]},{"title":"Connecting the cryocooler hoses and cables - scan room","shortdesc":"<p class=\"shortdesc\">Follow this procedure to connect the cryocooler hoses and cables in the scan room.<\/p>","href":"t_ConnectingTheCryocoolerHosesAndCablesScanRoom.html","attributes":{"data-id":"id_2001952"},"menu":{"hasChildren":false},"tocID":"id_2001952-d46e3130","topics":[]},{"title":"Connecting the magnet monitor cables","shortdesc":"<p class=\"shortdesc\">Follow this procedure to connect the magnet monitor cables.<\/p>","href":"t_ConnectingtheMagnetMonitorCables.html","attributes":{"data-id":"id_2001955"},"menu":{"hasChildren":false},"tocID":"id_2001955-d46e3234","topics":[]},{"title":"Confirming cryocooler connections","shortdesc":"<p class=\"shortdesc\">Follow this procedure to confirm cryocooler connections.<\/p>","href":"t_ConfirmingCryocoolerConnections.html","attributes":{"data-id":"id_2001956"},"menu":{"hasChildren":false},"tocID":"id_2001956-d46e3338","topics":[]},{"title":"Filling the Integrated Cooling Cabinet (ICC) primary water circuit","href":"t_FillingICCPrimaryWaterCircuit.html","attributes":{"data-id":"id_2001957"},"menu":{"hasChildren":false},"tocID":"id_2001957-d46e3442","topics":[]},{"title":"Removing LOTO - cryocooler compressor","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the cryocooler compressor breaker on the Main Disconnect Panel (MDP) before restoring cryocooler compressor power.<\/p>","href":"t_Removing-LOTO-CryocoolerCompressor-Premier_2.html","attributes":{"data-id":"id_2001784"},"menu":{"hasChildren":false},"tocID":"id_2001784-d46e3543","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_2.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":true},"tocID":"id_2001783-d46e3647","next":"id_2001783-d46e3647"}]});